import{createScreenLayer}from'./common/screen-lighting.mjs';import{createSceneLighting}from'./common/scene-lighting.mjs';import{createLightingSampler,createFrame}from'./common/day-night.mjs';
export const SOURCE_SHA='29e0513d5d7ed29ba72badb58a4082a0e594853a07ae8e197a6e33e01d6e53f8';
export function createEnvironment({source,manifest,indices,transmission}){const W=3072,H=1024,frame=createFrame(),sampler=createLightingSampler({night:[.4,.47,.6],schedule:{dawnStart:240,dayStart:540,duskStart:1020,nightStart:1260}}),light=createScreenLayer({manifest,indices,transmission,expectedSourceSHA:SOURCE_SHA,expectedSize:[W,H]});return function({camera=[0,0,960,540],minutes=720,lightOn=true,rest=false,bad=false}={}){const[cx,cy,w,h]=camera;if(!camera.every(Number.isInteger)||cx<0||cy<0||w<1||h<1||cx+w>W||cy+h>H||!Number.isFinite(minutes))throw Error('frame-contract');const out=new Uint8ClampedArray(w*h*4);for(let y=0;y<h;y++)out.set(source.subarray(((cy+y)*W+cx)*4,((cy+y)*W+cx+w)*4),y*w*4);if(lightOn&&!rest){sampler.sample(minutes,frame);const target=new Uint8ClampedArray(out.length),stats=createSceneLighting({nightTint:[.4,.47,.6],streetLayer:light,frameBytes:out.length})(out,target,{nightMix:frame.nightMix,camera,streetBad:bad});return{pixels:target,stats:{...stats,nightMix:frame.nightMix,water:0}}}return{pixels:out,stats:{nightMix:0,water:0}}}}
